import {bookingDatesReady, bookingPeriodLabel, changeBookingDate} from './bookingDates';
import ReviewDeadline from './ReviewDeadline';
import ModerationWorkspace from './ModerationWorkspace';
import {BookingChatLink} from './Chat';
import ShortNoticeBadge from './ShortNoticeBadge';
import BookingQuestions, {BookingQuestionSummary, bookingQuestionAnswers, missingBookingQuestions} from './BookingQuestions';
import {useEffect, useMemo, useRef, useState} from 'react';
import {Archive, AlertTriangle, Building2, CalendarCheck, CalendarRange, Check, ChevronRight, Clock3, History,
        MapPin, MessageSquarePlus, Repeat2, RotateCcw, Search, ShieldCheck, Trash2, UserRound, Users, Wrench, X} from 'lucide-react';
import {CLOSED_BOOKING_STATUSES as CLOSED, formatBookingDate as formatDate,
        formatBookingMoment as formatMoment, SOURCE_LABELS, STATUS_LABELS, todayIso, localIso, plural, eventFinished, readStored, writeStored, readDraft} from './bookingCenterConfig';
import {TransferDialog} from './AdminOperations';
import RoomEquipmentBlock from './RoomEquipmentBlock';
import { AttachmentList, AttachmentPicker, submitRequestWithFile, uploadAttachments, uploadFailureNotice } from './BookingAttachments';
import { ExtraRoomsPicker, RoomSetList, RoomSetCards, attachRoomSets, extraRoomsPayload, extraRoomsReady } from './RoomSets';
