// A series shows the state of the dates that still matter, not just of its first date.
const SERIES_STATUS_PRIORITY=['pending','in_progress','approved','completed','no_show'];
const eventStarted=item=>item.date<=localIso();
const groupSeriesItems=items=>{const groups=new Map();for(const item of items){const key=item.series_id?'series:'+item.series_id:'item:'+item.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item)}return [...groups.values()].map(group=>{group.sort((a,b)=>String(a.date+' '+a.time_start).localeCompare(String(b.date+' '+b.time_start)));const first=group[0];const shown=SERIES_STATUS_PRIORITY.map(status=>group.find(entry=>entry.status===status)).find(Boolean)||first;return group.length===1?first:{...shown,series_items:group,series_count:group.length,series_dates:[group[0].date,group[group.length-1].date]}})};
const entriesOf=item=>item.series_items||[item];
const canArchive=item=>{if(['pending','in_progress'].includes(item.status)&&!item.archived_at)return false;if(item.archived_at||CLOSED.includes(item.status))return true;return item.date<todayIso()};
const chronological=(a,b)=>String(a.date||'').localeCompare(String(b.date||''))||Number(a.id||0)-Number(b.id||0);

export default function AdminBookingCenter({request,notice,rooms,buildings,user,focusedBooking,initialRoom,clearInitialRoom,onChanged,active=true}){
  const [items,setItems]=useState([]);const [scope,setScope]=useState('all');const [tab,setTab]=useState('all');
  const emptyFilters={responsible:'',title:'',reference:'',room:'',building:'',department:'',eventFormat:'',dateFrom:'',dateTo:''};
  const [filters,setFilters]=useState(emptyFilters);const [detail,setDetail]=useState(null);const openFormKey=`admin-open-form-${user?.id}`;const bookingDraftKey=`admin-booking-draft-${user?.id}`;const [storedForm]=useState(()=>readStored(openFormKey));const [wizard,setWizardState]=useState(storedForm?.wizard||null);const setWizard=value=>setWizardState(value?{...value,token:value.token||Date.now()}:null);
  const [pastFrom,setPastFrom]=useState('');const [pastTo,setPastTo]=useState(()=>nowMonthEnd());
  const [,setClock]=useState(new Date());
  const [cancelTarget,setCancelTarget]=useState(null);const [deleteTarget,setDeleteTarget]=useState(null);const [editTarget,setEditTarget]=useState(null);const [loading,setLoading]=useState(true);
  const [departments,setDepartments]=useState([]);const [transferTarget,setTransferTarget]=useState(null);const [rejectTarget,setRejectTarget]=useState(null);
  const [highlightedBooking,setHighlightedBooking]=useState(null);// A tab or search can hide part of a series; decisions from the list must still cover the whole series.
  const wholeSeries=item=>{if(item.series_items||!item.series_id)return item;const group=groupSeriesItems(items.filter(entry=>entry.series_id===item.series_id))[0];return group?.series_items?group:item};
  const load=()=>{setLoading(true);return request(`/api/admin/booking-center?scope=${scope}&_=${Date.now()}`).then(data=>setItems([...data].sort(chronological))).catch(e=>notice(e.message)).finally(()=>setLoading(false))};
  const loadDepartments=()=>request('/api/departments').then(setDepartments).catch(()=>{});
  useEffect(()=>{if(active)load()},[scope,active]);
  useEffect(()=>{loadDepartments()},[]);
  useEffect(()=>{if(!initialRoom)return;setWizard({booking:{building_id:String(initialRoom.building_id),preferred_room_id:initialRoom.id,preferred_room:initialRoom}});clearInitialRoom?.()},[initialRoom]);
  useEffect(()=>{writeStored(openFormKey,wizard?{wizard}:null);if(!wizard)writeStored(bookingDraftKey,null)},[wizard]);
  useEffect(()=>{const timer=setInterval(()=>setClock(new Date()),30000);return()=>clearInterval(timer)},[]);
  useEffect(()=>{if(!focusedBooking?.id)return;setScope('all');setTab('all');setFilters(emptyFilters);setHighlightedBooking(focusedBooking.id);const timer=setTimeout(()=>setHighlightedBooking(null),4200);return()=>clearTimeout(timer)},[focusedBooking?.token]);
  const now=todayIso();
  const normalized=value=>String(value||'').trim().toLocaleLowerCase('ru-RU');
  const updateFilter=(key,value)=>setFilters(current=>({...current,[key]:value}));
  const filterCount=Object.values(filters).filter(value=>String(value).trim()).length;
  const buildingOptions=[...new Set(items.map(item=>item.building).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));
  const departmentOptions=[...new Set(items.map(item=>item.department_name).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));
  const eventFormatOptions=[...new Set(items.map(item=>item.event_format).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ru'));
  const visible=items.filter(item=>{
    const inTab=tab==='today'?!item.archived_at&&item.date===now:
      tab==='upcoming'?!item.archived_at&&item.date>now&&!CLOSED.includes(item.status):
      tab==='cancelled'?!item.archived_at&&['cancelled','cancelled_by_user','cancelled_by_admin'].includes(item.status)&&item.cancellation_reason&&item.cancelled_by:
      tab==='past'?!item.archived_at&&item.date<now&&(!pastFrom||item.date>=pastFrom)&&(!pastTo||item.date<=pastTo):
      tab==='archive'?Boolean(item.archived_at):!item.archived_at;
    if(!inTab)return false;
    if(filters.responsible&&!normalized(`${item.customer_name||''} ${item.booked_by||''} ${item.owner_name||''}`).includes(normalized(filters.responsible)))return false;
    if(filters.title&&!normalized(item.title).includes(normalized(filters.title)))return false;
    if(filters.reference&&!normalized(item.external_reference).includes(normalized(filters.reference)))return false;
    if(filters.room&&!normalized(item.room_number).includes(normalized(filters.room)))return false;
    if(filters.building&&item.building!==filters.building)return false;
    if(filters.department&&item.department_name!==filters.department)return false;
    if(filters.eventFormat&&item.event_format!==filters.eventFormat)return false;
    if(filters.dateFrom&&item.date<filters.dateFrom)return false;
    if(filters.dateTo&&item.date>filters.dateTo)return false;
    return true;
  });
  const refresh=async(message)=>{if(message)notice(message);setDetail(null);setCancelTarget(null);setEditTarget(null);await load();onChanged?.()};
  const openDetail=async item=>{try{setDetail(await request(`/api/admin/booking-center/${item.id}`))}catch(e){notice(e.message)}};
  const setStatus=async(item,status,reason=null)=>{const series=Boolean(item.series_items);try{await request(series?`/api/admin/booking-series/${item.series_id}/status`:`/api/admin/booking-center/${item.id}/status`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,reason})});setRejectTarget(null);refresh(series?(status==='approved'?'Серия бронирований подтверждена':'Серия бронирований отклонена'):status==='approved'?'Бронирование подтверждено':status==='rejected'?'Заявка отклонена':'Статус бронирования обновлён')}catch(e){notice(e.message)}};
  const setArchived=async(item,archived=true)=>{try{const ids=entriesOf(item).filter(entry=>archived?!entry.archived_at&&canArchive(entry):entry.archived_at).map(entry=>entry.id);if(ids.length)await request('/api/admin/booking-bulk/archive',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids,archived})});refresh(archived?'Бронирование перенесено в архив':'Бронирование восстановлено из архива')}catch(e){notice(e.message)}};
  return <section className="content-page admin-booking-center">
    <header className="booking-center-heading"><div><small>РАБОЧИЙ ЦЕНТР АДМИНИСТРАТОРА</small><h1>Мои бронирования</h1></div></header>
    <div className="booking-center-controls"><div className="booking-tabs">{[['all','Все бронирования'],['today','Сегодня'],['upcoming','Предстоящие'],['cancelled','Отменённые'],['past','Прошедшие'],['archive','Архив']].map(([key,label])=><button key={key} className={tab===key?'active':''} onClick={()=>setTab(key)}>{label}</button>)}</div><div className="booking-scope"><button className={scope==='mine'?'active':''} onClick={()=>setScope('mine')}>Только мои</button><button className={scope==='all'?'active':''} onClick={()=>setScope('all')}>Все бронирования</button></div></div>
    {tab==='past'&&<div className="past-booking-calendar"><CalendarCheck/><b>Период прошедших бронирований</b><label>С <input type="date" lang="ru-RU" max={now} value={pastFrom} onChange={e=>setPastFrom(e.target.value)}/></label><label>По <input type="date" lang="ru-RU" max={now} value={pastTo} onChange={e=>setPastTo(e.target.value)}/></label><button className="secondary" onClick={()=>{setPastFrom('');setPastTo(nowMonthEnd())}}>Сбросить</button></div>}
    <section className="admin-booking-filters" aria-label="Фильтры бронирований"><header><div><Search/>{filterCount>0&&<span>{filterCount}</span>}</div><small>{visible.length} {plural(visible.length,['запись','записи','записей'])}</small>{filterCount>0&&<button type="button" onClick={()=>setFilters(emptyFilters)}><RotateCcw/>Сбросить</button>}</header><div className="admin-booking-filter-grid">
      <label><span>ФИО ответственного</span><input value={filters.responsible} onChange={e=>updateFilter('responsible',e.target.value)} placeholder="Введите ФИО"/></label>
      <label><span>Название программы</span><input value={filters.title} onChange={e=>updateFilter('title',e.target.value)} placeholder="Введите название"/></label>
      <label><span>Номер заявки</span><input value={filters.reference} onChange={e=>updateFilter('reference',e.target.value)} placeholder="Введите номер"/></label>
      <label><span>Аудитория</span><input value={filters.room} onChange={e=>updateFilter('room',e.target.value)} placeholder="Например: 2254"/></label>
      <label><span>Корпус</span><select value={filters.building} onChange={e=>updateFilter('building',e.target.value)}><option value="">Все корпуса</option>{buildingOptions.map(value=><option key={value}>{value}</option>)}</select></label>
      <label><span>Подразделение / центр</span><select value={filters.department} onChange={e=>updateFilter('department',e.target.value)}><option value="">Все подразделения</option>{departmentOptions.map(value=><option key={value}>{value}</option>)}</select></label>
      <label><span>Тип мероприятия</span><select value={filters.eventFormat} onChange={e=>updateFilter('eventFormat',e.target.value)}><option value="">Все типы</option>{eventFormatOptions.map(value=><option key={value}>{value}</option>)}</select></label>
      <details className="admin-booking-date-filter" open={Boolean(filters.dateFrom||filters.dateTo)||undefined}><summary><CalendarRange/>Период проведения{(filters.dateFrom||filters.dateTo)&&<i>выбран</i>}</summary><div><label><span>С даты</span><input type="date" lang="ru-RU" value={filters.dateFrom} max={filters.dateTo||undefined} onChange={e=>updateFilter('dateFrom',e.target.value)}/></label><label><span>По дату</span><input type="date" lang="ru-RU" value={filters.dateTo} min={filters.dateFrom||undefined} onChange={e=>updateFilter('dateTo',e.target.value)}/></label><small>Фильтр учитывает даты проведения мероприятия.</small></div></details>
    </div></section>
    {loading&&<p role="status">Загружаем бронирования…</p>}<ModerationWorkspace records={visible} active={active} request={request} notice={notice} focusId={highlightedBooking} openBooking={openDetail} archiveBooking={item=>setArchived(wholeSeries(item),!item.archived_at)} replaceBooking={item=>setWizard({booking:item,replace:true})} deleteBooking={item=>setDeleteTarget(wholeSeries(item))}/>
    {wizard&&<PhoneBookingWizard key={wizard.token} draftKey={bookingDraftKey} draftToken={wizard.token} initial={wizard.booking} replaceId={wizard.replace?wizard.booking.id:null} rooms={rooms} buildings={buildings} departments={departments} request={request} user={user} close={()=>setWizard(null)} done={message=>{setWizard(null);setTab('all');setScope('all');refresh(message||'Бронирование подтверждено и добавлено в календарь')}}/>}
    {detail&&<BookingDetail item={detail} viewerId={user.id} request={request} reload={()=>openDetail(detail)} close={()=>setDetail(null)} edit={()=>setEditTarget(detail)} alternatives={()=>{setDetail(null);setWizard({booking:detail,replace:true})}} transfer={()=>setTransferTarget(detail)} cancel={()=>setCancelTarget(detail)} remove={()=>setDeleteTarget(detail)} archive={()=>setArchived(detail,!detail.archived_at)} status={status=>setStatus(detail,status)}/>}
    {cancelTarget&&<CancelDialog item={cancelTarget} request={request} close={()=>setCancelTarget(null)} done={()=>refresh('Отмена сохранена в истории')}/>}
    {deleteTarget&&<DeleteBookingDialog item={deleteTarget} request={request} close={()=>setDeleteTarget(null)} done={()=>{const series=Boolean(deleteTarget.series_items);setDeleteTarget(null);refresh(series?'Серия полностью удалена':'Ошибочная бронь полностью удалена')}}/>}
    {editTarget&&<EditBooking item={editTarget} rooms={rooms} departments={departments} request={request} close={()=>setEditTarget(null)} done={()=>refresh('Бронирование обновлено')}/>}
    {transferTarget&&<TransferDialog item={transferTarget} rooms={rooms} request={request} close={()=>setTransferTarget(null)} done={()=>{setTransferTarget(null);refresh('Бронирование перенесено, исходная запись сохранена в истории')}}/>}
    {rejectTarget&&<RejectBookingDialog item={rejectTarget} close={()=>setRejectTarget(null)} submit={reason=>setStatus(rejectTarget,'rejected',reason)}/>}
  </section>
}


function BookingSkeleton(){return <div className="booking-skeleton" aria-label="Загрузка бронирований">{Array.from({length:4},(_,index)=><article key={index}><i/><span><b/><b/><b/></span><em/></article>)}</div>}

function nowMonthEnd(){const value=new Date();return localIso(new Date(value.getFullYear(),value.getMonth()+1,0))}

function BookingCard({item,viewerId,showNumber,highlighted,open,openEntry,approve,reject,alternatives,repeat,transfer,cancel,remove,archive}){const series=Boolean(item.series_items);const archivable=entriesOf(item).some(entry=>entry.archived_at||canArchive(entry));const person=item.customer_name||item.booked_by;const owner=item.owner_name||item.booked_by;const kindLabels={maintenance:'Ремонт',setup:'Застройка',teardown:'Демонтаж',unavailable:'Недоступна'};return <article id={`admin-booking-${item.id}`} data-booking-ids={entriesOf(item).flatMap(entry=>[entry.id,...(entry.set_extras||[]).map(extra=>extra.id)]).join(' ')} className={`admin-booking-card ${highlighted?'booking-focus-highlight':''} ${item.has_conflict?'conflict':''} kind-${item.record_kind||'booking'}`}>
  <button className="booking-card-delete-icon" onClick={remove} title={series?'Удалить всю серию':'Удалить бронь'} aria-label={`Удалить ${series?'серию':'бронь'} ${item.title}`}><Trash2/></button>
  <div className="booking-card-date"><strong>{formatDate(item.date)}</strong>{item.series_dates&&<b>по {formatDate(item.series_dates[1])}</b>}<span>{SOURCE_LABELS[item.source]||item.source}</span>{item.created_at&&<small className="booking-created-at">Создана: {formatMoment(item.created_at)}</small>}</div>
  <div className="booking-card-main">{showNumber&&<small className="booking-found-number">Номер заявки: {item.external_reference||'не указан'}</small>}<div className="booking-card-title"><em className={`status ${item.status}`}>{item.review_expired?'Не подтверждена · просрочена':STATUS_LABELS[item.status]||item.status}</em>{item.record_kind!=='booking'&&<em className={`record-kind ${item.record_kind}`}>{kindLabels[item.record_kind]}</em>}{showNumber&&item.archived_at&&<em className="room-set-badge">В архиве</em>}{item.series_id&&<em className="series-pill">Серия</em>}{item.set_extras?.length>0&&<em className="room-set-badge">Комплект · {item.set_extras.length+1} ауд.</em>}{item.parent_booking_id&&<em className="room-set-badge">Дополнительная аудитория</em>}{item.has_conflict&&<em className="conflict-pill"><AlertTriangle/>Конфликт</em>}</div><ReviewDeadline item={item}/><ShortNoticeBadge item={item}/><h3>{item.title}</h3>{item.series_items&&<div className="series-summary"><b>Серия бронирований</b><span>{item.series_count} записей · {formatDate(item.series_dates[0])} — {formatDate(item.series_dates[1])}</span><small>Нажмите на дату, чтобы открыть отдельную бронь серии.</small><div className="series-entry-list">{item.series_items.map(entry=><button type="button" key={entry.id} onClick={()=>openEntry(entry)}>{formatDate(entry.date)} · Ауд. {entry.room_number}{entry.status!==item.status?` · ${STATUS_LABELS[entry.status]||entry.status}`:''}</button>)}</div></div>}{item.set_extras?.length>0?<RoomSetCards main={item} extras={item.set_extras} actions={extra=><button type="button" className="secondary" onClick={()=>openEntry(extra)}>Подробности</button>}/>:<div className="booking-room-highlight" style={{'--building-color':item.color}}><span><Building2/>Корпус <b>{item.building}</b></span><span>Аудитория <strong>{item.room_number}</strong></span></div>}<div className="booking-card-meta"><span><b>Подразделение:</b> {item.department_name||'не указано'}</span><span><UserRound/>{person}</span>{owner!==person&&<span><ShieldCheck/>{owner}</span>}<span><Users/>{item.participants||'—'} участников</span>{item.external_reference&&<span>Номер заявки: {item.external_reference}</span>}</div>{item.status==='pending'&&<div className="soft-hold-note"><Clock3/>Мягкий резерв до {item.hold_expires_at?formatMoment(item.hold_expires_at):'решения администратора'}</div>}{item.transfer_reason&&<div className="booking-cancellation-note"><b>Причина переноса: {item.transfer_reason}</b>{item.previous_booking_id&&<small>Исходная бронь № {item.previous_booking_id}</small>}</div>}{item.cancellation_reason&&<div className="booking-cancellation-note"><b>Причина: {item.cancellation_reason}</b><span>{item.cancellation_comment}</span><small>Отменил(а): {item.cancelled_by}</small></div>}</div>
  <div className="booking-card-actions"><BookingChatLink item={item}/>{!series&&<button className="secondary" onClick={open}>Подробности<ChevronRight/></button>}{item.record_kind==='booking'&&!series&&<button className="secondary repeat-booking" onClick={repeat} title="Создать новую бронь с теми же данными"><Repeat2/>Повторить</button>}{item.status==='pending'&&<><button className="soft-danger" onClick={reject}>{series?'Отказать по серии':'Отказать'}</button><button className="primary" onClick={approve}>{series?'Подтвердить серию':'Подтвердить'}</button></>} {!CLOSED.includes(item.status)&&item.status!=='pending'&&(item.record_kind==='booking'||series)&&<>{!series&&<><button className="secondary" onClick={alternatives}>Найти замену</button><button className="secondary" onClick={transfer}>Перенести</button></>}<button className="danger-link" onClick={cancel}>{series?'Отменить серию':'Отменить'}</button></>}{archivable&&<button className="archive-button" onClick={archive}><Archive/>{item.archived_at?(series?'Вернуть серию из архива':'Вернуть из архива'):(series?'Серию в архив':'В архив')}</button>}</div>
</article>}

// Also used by the calendar for both roles (App.jsx): for a user it sends a request for moderation.
export function PhoneBookingWizard({initial,replaceId,rooms,buildings,departments,request,user,close,done,draftKey,draftToken,onSeries}){
  const asUser=user?.role!=='admin';const availabilityUrl=asUser?'/api/availability':'/api/admin/availability';
  // Opened for one room (calendar "+", room card): book exactly that room, no search among other rooms.
  const fixedRoom=!replaceId&&initial?.fixed_room?initial.preferred_room:null;
  const fixedCapacity=fixedRoom?Math.max(Number(fixedRoom.capacity)||0,Number(fixedRoom.max_capacity)||0):0;
  const [departmentList,setDepartmentList]=useState(departments||[]);
  const [draft]=useState(()=>readDraft(draftKey,draftToken));
  const [step,setStep]=useState(1);const [results,setResults]=useState(null);const [selected,setSelected]=useState(draft?.selected||initial?.preferred_room||null);const [error,setError]=useState('');const [saving,setSaving]=useState(false);
  const [form,setForm]=useState(()=>draft?.form?({...draft.form,date_end:draft.form.date_end??draft.form.date}):{date:initial?.date||'',date_end:initial?.date_end||initial?.date||'',participants:initial?.participants||'',building_id:initial?.building_id?String(initial.building_id):'',title:initial?.title||'',...eventFormatState(initial?.event_format),customer_name:initial?.customer_name||user?.full_name||'',customer_contact:initial?.customer_contact||(asUser?user?.phone||'':''),department_name:initial?.department_name||user?.department||'',comment:initial?.comment||'',...bookingQuestionAnswers(initial),department_id:initial?.department_id||'',external_channel:initial?.external_channel||(initial?.preferred_room&&!initial?.id?'service':'phone'),external_reference:initial?.external_reference||'',external_url:initial?.external_url||''});
  useEffect(()=>{if(departments)setDepartmentList(departments)},[departments]);
  useEffect(()=>{if(departments)return;request('/api/departments').then(list=>{setDepartmentList(list);if(asUser)setForm(current=>{if(current.department_id)return current;const known=list.find(item=>item.name.toLowerCase()===String(current.department_name||'').trim().toLowerCase());return known?{...current,department_id:String(known.id)}:{...current,department_id:''}})}).catch(()=>{})},[]);
  useEffect(()=>{if(draftKey)writeStored(draftKey,{token:draftToken,form,selected})},[form,selected]);
  const [files,setFiles]=useState([]);const [extraRooms,setExtraRooms]=useState([]);const [invalid,setInvalid]=useState([]);const availabilityRef=useRef(null);const availabilitySeq=useRef(0);
  const equipmentRoom=selected?(rooms.find(room=>room.id===selected.id)||selected):null;
  const change=(key,value)=>{if(key==='date'){setError('')}setForm(current=>changeBookingDate(current,key,value));if(key==='date'||key==='date_end'){setExtraRooms([])}};
  const capacityExceeded=Boolean(fixedRoom&&fixedCapacity>0&&Number(form.participants)>fixedCapacity);
  const validateRequired=()=>{const required={date:form.date,date_end:bookingDatesReady(form),participants:Number.isInteger(Number(form.participants))&&Number(form.participants)>0&&Number(form.participants)<=5000,event_format:eventFormatReady(form),title:form.title.trim().length>=2,customer_name:form.customer_name.trim().length>=2,external_reference:(form.external_reference||'').trim().length>0,customer_contact:form.customer_contact.trim().length>=3,department_id:Boolean(form.department_id),attachment:Boolean(replaceId||files.length)};const missing=[...Object.entries(required).filter(([,value])=>!value).map(([key])=>key),...missingBookingQuestions(form)];if(capacityExceeded&&!missing.includes('participants'))missing.push('participants');if(missing.length){if(capacityExceeded)window.setTimeout(()=>document.getElementById('fixed-room-participants')?.focus(),0);setInvalid(missing);setError('');setStep(1);return false}setInvalid([]);setError('');return true};
  const chooseRoom=room=>{if(!validateRequired())return;setSelected(room);setStep(3)};
  const fetchAvailability=async goNext=>{setError('');const seq=++availabilitySeq.current;try{const body={date:form.date,date_end:form.date_end,participants:fixedRoom?1:Number(form.participants)||1,building_id:fixedRoom?fixedRoom.building_id||null:form.building_id?Number(form.building_id):null,exclude_booking_id:initial?.id||null};const data=await request(availabilityUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(seq!==availabilitySeq.current)return;setResults(data);const preferred=data.free.find(room=>room.id===initial?.preferred_room_id);if(goNext&&preferred){setSelected(preferred);setStep(3)}else if(goNext)setStep(2);else window.setTimeout(()=>availabilityRef.current?.scrollIntoView({behavior:'smooth',block:'nearest'}),120)}catch(e){if(seq===availabilitySeq.current){setError(e.message)}}};
  useEffect(()=>{if(step!==1)return;availabilitySeq.current+=1;/* Invalidate in-flight responses for the previous time. */setResults(null);setSelected(null);if(!bookingDatesReady(form)||(!fixedRoom&&!(Number(form.participants)>0))){setResults(null);return}const timer=setTimeout(()=>fetchAvailability(false),450);return()=>clearTimeout(timer)},[step,form.date,form.date_end,form.building_id,fixedRoom?null:form.participants]);
  const check=()=>{if(validateRequired())fetchAvailability(true)};
  const submit=async()=>{if(!validateRequired())return;if(asUser&&!files.length){setError('Прикрепите файл с обоснованием заявки');return;}if(!selected||!displayedResults){setError('Сначала выберите свободную аудиторию и дождитесь проверки доступности');return}if(Number(form.participants)>Math.max(Number(selected.capacity)||0,Number(selected.max_capacity)||0)){setInvalid(['participants']);setError('Количество участников превышает допустимую вместимость аудитории');return}if(!replaceId&&!extraRoomsReady(extraRooms)){setError('Для каждой дополнительной аудитории выберите аудиторию и назначение');return}setSaving(true);setError('');const event_format=eventFormatValue(form);try{if(replaceId){await request(`/api/admin/booking-center/${replaceId}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({room_id:selected.id,date:form.date,event_format,title:form.title.trim(),comment:form.comment.trim()||null,...bookingQuestionAnswers(form),customer_name:form.customer_name.trim(),customer_contact:form.customer_contact.trim()||null,participants:Number(form.participants)||null,department_id:null,department_name:form.department_name.trim(),external_reference:(form.external_reference||'').trim()})});const failed=await uploadAttachments(request,{bookingId:replaceId},files);done('Бронь перенесена в подобранную аудиторию'+uploadFailureNotice(failed));return}if(asUser){const departmentPayload={department_id:null,department_name:form.department_name.trim()};await submitRequestWithFile(request,{room_id:selected.id,date:form.date,date_end:form.date_end,event_format,title:form.title.trim(),booking_type:'other',comment:form.comment.trim()||null,...bookingQuestionAnswers(form),participants:Number(form.participants)||null,...departmentPayload,customer_name:form.customer_name.trim(),customer_contact:form.customer_contact.trim()||null,external_reference:(form.external_reference||'').trim(),extra_rooms:extraRoomsPayload(extraRooms)},files[0]);done('Заявка отправлена на согласование');return}const created=await request('/api/admin/phone-bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({room_id:selected.id,date:form.date,date_end:form.date_end,event_format,title:form.title.trim(),booking_type:'other',group_name:null,teacher:null,comment:form.comment.trim()||null,...bookingQuestionAnswers(form),customer_name:form.customer_name.trim(),customer_contact:form.customer_contact.trim()||null,participants:Number(form.participants)||null,department_id:null,department_name:form.department_name.trim(),external_reference:(form.external_reference||'').trim(),extra_rooms:extraRoomsPayload(extraRooms)})});const failed=await uploadAttachments(request,created.series_id?{seriesId:created.series_id}:{bookingId:created.id},files);done(failed.length?'Бронирование подтверждено.'+uploadFailureNotice(failed):undefined)}catch(e){setError(e.message);setSaving(false)}};
  const preferredResult=results?.free.find(room=>room.id===initial?.preferred_room_id);const displayedResults=results&&preferredResult?{...results,free:[preferredResult],summary:{...results.summary,free:1}}:results;
  const searchReady=Boolean(bookingDatesReady(form)&&(fixedRoom||Number(form.participants)>0));
  useEffect(()=>{if(fixedRoom){setSelected(results?results.free.find(room=>room.id===fixedRoom.id)||null:fixedRoom);return}if(results&&selected&&!results.free.some(room=>room.id===selected.id))setSelected(null)},[results]);
  const mark=(key,ok)=>ok?'complete':invalid.includes(key)?'invalid':'';
  const candidateRooms=rooms.filter(room=>(!form.building_id||String(room.building_id)===String(form.building_id))&&(!Number(form.participants)||Math.max(room.capacity,room.max_capacity||0)>=Number(form.participants)));
  const shownRooms=displayedResults?displayedResults.free:initial?.preferred_room?[initial.preferred_room]:candidateRooms;
  const pick=room=>{if(!displayedResults){validateRequired();return;}if(selected?.id===room.id){setSelected(null);return}setExtraRooms(current=>current.filter(extra=>Number(extra.room_id)!==Number(room.id)));setSelected(room)};
  // Same layout and classes as the user's request form (UserBookingPortal); an admin booking is confirmed at once.
  return <div className="admin-series-overlay" role="dialog" aria-modal="true" onClick={event=>{if(event.target===event.currentTarget&&!saving)close()}}><div className="user-booking-portal admin-series-portal"><div className="user-request-layout has-matches series-modal-mode">
    <div className="series-modal-banner"><div><small>{replaceId?`ПОДБОР ЗАМЕНЫ ДЛЯ БРОНИ № ${replaceId}`:asUser?'НОВАЯ ЗАЯВКА':'ОФОРМЛЕНИЕ БРОНИ'}</small><h2>{replaceId?'Найти замену':asUser?'Забронировать аудиторию':'Оформить бронь'}</h2><p>{replaceId?'Бронь будет перенесена в выбранную аудиторию':asUser?'Заявка будет отправлена администратору на согласование':'Бронь будет сразу подтверждена и появится в календаре'}</p></div><div className="series-modal-banner-actions">{onSeries&&!replaceId&&user?.role==='admin'&&<button type="button" className="secondary" onClick={()=>onSeries(initial?.preferred_room||null)}><Repeat2/>Серия бронирования</button>}<button type="button" className="icon" onClick={close}>Закрыть</button></div></div>
    <section className="user-request-form"><header><span>1</span><div><h2>Параметры мероприятия</h2><p>{replaceId?'Выберите дату и аудиторию для этой записи.':'Аудитория бронируется на весь рабочий день на каждую дату периода.'}</p></div></header>
      {initial?.preferred_room&&<div className="user-preselected-room" style={{'--room-color':initial.preferred_room.color}}><img src={initial.preferred_room.images?.[0]} alt=""/><span><small>ВЫБРАННАЯ АУДИТОРИЯ</small><b>{initial.preferred_room.building} · аудитория {initial.preferred_room.number}</b><em>{initial.preferred_room.name} · {initial.preferred_room.capacity} мест</em></span><Check/></div>}
      <div className="user-request-fields">
        <label className={mark('date',form.date)}><span>{replaceId?'Новая дата':'Дата начала'} *</span><RussianDatePicker value={form.date} onChange={value=>change('date',value)}/></label>
        {!replaceId&&<label className={mark('date_end',bookingDatesReady(form))}><span>Дата окончания *</span><RussianDatePicker value={form.date_end} min={form.date||undefined} onChange={value=>change('date_end',value)}/></label>}
        <label className={capacityExceeded?'invalid capacity-invalid':mark('participants',Number.isInteger(Number(form.participants))&&Number(form.participants)>0&&Number(form.participants)<=5000)}><span>Количество участников *</span><input id="fixed-room-participants" type="number" min="1" max={fixedRoom&&fixedCapacity?fixedCapacity:5000} value={form.participants} onChange={e=>change('participants',e.target.value)} placeholder="Например, 25" aria-invalid={capacityExceeded} aria-describedby={capacityExceeded?'fixed-capacity-warning':undefined}/>{capacityExceeded&&<small id="fixed-capacity-warning" className="booking-lead-warning capacity-warning" role="alert">Превышено количество участников. Максимум для аудитории {fixedRoom.number} — {fixedCapacity} мест.</small>}</label>{!fixedRoom&&<>
        <label><span>Корпус</span><select value={form.building_id} onChange={e=>change('building_id',e.target.value)}><option value="">Любой корпус</option>{buildings.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select></label>
        </>}
        <EventFormatField form={form} update={change} invalid={invalid.includes('event_format')}/>
        <label className={`full ${mark('title',form.title.trim().length>=2)}`}><span>Название мероприятия *</span><input value={form.title} onChange={e=>change('title',e.target.value)} placeholder="Дополнительная профессиональная программа повышения квалификации «Регулярный менеджмент»"/></label>
        <label className={`full ${mark('department_id',Boolean(form.department_id))}`}><span>Подразделение *</span><DepartmentSelect items={departmentList} value={form.department_id} onChange={(id,chosen)=>{change('department_id',id);change('department_name',chosen.name)}}/></label>
        <label className={mark('customer_name',form.customer_name.trim().length>=2)}><span>ФИО ответственного *</span><input value={form.customer_name} onChange={e=>change('customer_name',e.target.value)} placeholder="Иванова Анна Сергеевна"/></label>
        <label className={mark('external_reference',(form.external_reference||'').trim().length>0)}><span>Номер заявки *</span><input value={form.external_reference||''} onChange={e=>change('external_reference',e.target.value)} maxLength={120} placeholder="Введите номер заявки"/></label>
        <label className={mark('customer_contact',form.customer_contact.trim().length>=3)}><span>Телефон *</span><input type="tel" value={form.customer_contact} onChange={e=>change('customer_contact',e.target.value)} placeholder="+7 999 000-00-00"/></label>
        <RoomEquipmentBlock className="full" rooms={[equipmentRoom]}/>
        <BookingQuestions form={form} update={change} attempted={invalid.length>0}/><label className="full"><span>Комментарий</span><textarea value={form.comment} onChange={e=>change('comment',e.target.value)} placeholder="Необязательное поле: важные детали или пожелания"/></label><div className={`full required-attachment ${invalid.includes('attachment')?'invalid':''}`}><AttachmentPicker single={asUser} files={files} onChange={setFiles}/>{invalid.includes('attachment')&&<small>Прикрепите файл перед отправкой формы</small>}</div>
      </div>
      {!fixedRoom&&searchReady&&<p className={`user-search-status ready`}><Search/>{displayedResults?`Найдено свободных аудиторий: ${displayedResults.free.length}. Список обновляется сам при изменении параметров.`:'Подбираем аудитории…'}</p>}
    </section>
    {fixedRoom?<aside className="user-match-pane" ref={availabilityRef}><section className="user-availability fixed-room-pane">
      <header><div><small>ВЫБРАННАЯ АУДИТОРИЯ</small><h2>Аудитория {fixedRoom.number}</h2><p>{fixedRoom.building} · {fixedRoom.capacity} мест{searchReady?` · ${bookingPeriodLabel(form.date,form.date_end)}`:''}</p></div></header>
      <div className={`fixed-room-status ${!searchReady?'':!displayedResults?'':selected?'free':'busy'}`}>{selected&&displayedResults?<Check/>:displayedResults&&searchReady?<AlertTriangle/>:<Clock3/>}<span>{!searchReady?'Укажите даты — проверим, свободна ли аудитория.':!displayedResults?'Проверяем занятость…':selected?'Аудитория свободна на выбранные даты. При необходимости добавьте дополнительные аудитории ниже.' :'Аудитория занята в выбранный период — измените даты.'}</span></div>
      {displayedResults&&selected&&<ExtraRoomsPicker request={request} availabilityUrl={availabilityUrl} date={form.date} dateEnd={form.date_end} mainRoomId={selected.id} roomCatalog={rooms} value={extraRooms} onChange={setExtraRooms}/>}
      {error&&<p className="error admin-series-error">{error}</p>}
      {<footer><div><Check/><span><small>ВЫБРАНО</small><b>{fixedRoom.building} · аудитория {fixedRoom.number}{extraRooms.length?` + ещё ${extraRooms.length}`:''}</b></span></div><button className="primary" disabled={saving} onClick={submit}><CalendarCheck/>{saving?'Сохраняем…':asUser?'Отправить на согласование':'Подтвердить и забронировать'}</button></footer>}
    </section></aside>:
    <aside className="user-match-pane" ref={availabilityRef}><section className="user-availability">
      <header><div><small>{displayedResults?'РЕЗУЛЬТАТ ПОДБОРА':'ПОДХОДЯЩИЕ ВАРИАНТЫ'}</small><h2>{displayedResults?'Свободные аудитории':'Подходящие аудитории'}</h2><p>{displayedResults?`${bookingPeriodLabel(form.date,form.date_end)} · ${form.participants} участников`:'Укажите даты и количество участников, чтобы проверить занятость.'}</p></div><span>{shownRooms.length}</span></header>
      {shownRooms.length?<div className="user-available-grid">{(selected&&displayedResults?shownRooms.filter(room=>room.id===selected.id):shownRooms).map(room=><button type="button" className={selected?.id===room.id&&displayedResults?'selected':''} onClick={()=>pick(room)} key={room.id}><img src={room.images?.[0]} alt=""/><div><small>{room.building}</small><h3>Аудитория {room.number}</h3><p>{room.capacity} мест{room.over_capacity?' (нужны доп. места)':''}</p>{room.pending_requests?.length>0&&<em className="soft-request-warning">Параллельных заявок: {room.pending_requests.length}</em>}</div>{displayedResults?selected?.id===room.id?<Check/>:<ChevronRight/>:<Clock3/>}</button>)}</div>
        :<div className="user-no-availability"><AlertTriangle/><b>{displayedResults?'Свободных аудиторий нет':'Подходящих аудиторий нет'}</b><span>Измените вместимость, корпус или оснащение.</span></div>}
      {displayedResults&&selected&&<button type="button" className="secondary change-selected-room" onClick={()=>setSelected(null)}>Выбрать другую аудиторию</button>}
      {displayedResults&&selected&&!replaceId&&<ExtraRoomsPicker request={request} availabilityUrl={availabilityUrl} date={form.date} dateEnd={form.date_end} mainRoomId={selected.id} roomCatalog={rooms} value={extraRooms} onChange={setExtraRooms}/>}
      {error&&<p className="error admin-series-error">{error}</p>}
      {displayedResults&&selected&&<footer><div><Check/><span><small>ВЫБРАНО</small><b>{selected.building} · аудитория {selected.number}</b></span></div><button className="primary" disabled={saving} onClick={submit}><CalendarCheck/>{saving?'Сохраняем…':replaceId?'Перенести бронь в эту аудиторию':asUser?'Отправить на согласование':'Подтвердить и забронировать'}</button></footer>}
    </section></aside>}
  </div></div></div>
}


function RussianDatePicker({value,onChange,min}){return <input type="date" lang="ru-RU" min={min} value={value} onChange={event=>onChange(event.target.value)}/>}

function InlineAvailableRooms({results,choose}){return <section className="inline-available"><header><div><small>ДОСТУПНЫ НА ВЫБРАННУЮ ДАТУ</small><h3>Свободные аудитории выбранного корпуса</h3></div><span>{results.free.length}</span></header><div>{results.free.length?results.free.map(room=><button type="button" key={room.id} onClick={()=>choose(room)}><img src={room.images?.[0]} alt=""/><span><b>Ауд. {room.number}</b><small>{room.building}</small><em>{room.capacity} мест{room.over_capacity?' (нужны доп. места)':''}</em>{room.pending_requests?.length>0&&<strong className="soft-request-warning">Параллельных заявок: {room.pending_requests.length}</strong>}</span><ChevronRight/></button>):<p>По заданным параметрам свободных аудиторий нет. Измените время, вместимость или оснащение.</p>}</div></section>}

function AvailabilityResults({results,choose}){const groups=[['free','Подходит и свободна','green'],['occupied','Занята на выбранную дату','red'],['alternatives','Возможные альтернативы','blue']];return <div className="availability-results"><div className="availability-summary"><ShieldCheck/><span><b>{results.summary.free} подходящих свободных</b>Ещё {results.summary.alternatives} альтернатив и {results.summary.occupied} занятых вариантов</span></div>{groups.map(([key,title,tone])=><section key={key}><h3 className={tone}>{title}<span>{results[key].length}</span></h3><div>{results[key].length?results[key].map(room=><article className={`availability-room ${tone}`} key={room.id}><img src={room.images?.[0]} alt=""/><div><b>Ауд. {room.number}</b><small>{room.building}</small><p>{room.capacity} мест{room.over_capacity?' (нужны доп. места)':''}</p>{room.conflict&&<em>Занята: {room.conflict.title}</em>}{room.pending_requests?.length>0&&<strong className="soft-request-warning">Есть параллельные заявки: {room.pending_requests.length}</strong>}</div>{key!=='occupied'&&<button className="primary" onClick={()=>choose(room)}>Выбрать</button>}</article>):<p className="availability-empty">В этой группе вариантов нет</p>}</div></section>)}</div>}

function BookingDetail({item,viewerId,request,reload,close,edit,alternatives,transfer,cancel,remove,archive,status}){
  const [comment,setComment]=useState('');const [commentError,setCommentError]=useState('');
  const [extraRows,setExtraRows]=useState([]);const [extraBusy,setExtraBusy]=useState(false);const [extraError,setExtraError]=useState('');
  const addExtras=async()=>{if(!extraRoomsReady(extraRows)){setExtraError('Для каждой аудитории выберите аудиторию и назначение');return}setExtraBusy(true);setExtraError('');try{await request(`/api/admin/booking-center/${item.id}/extra-rooms`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({extra_rooms:extraRoomsPayload(extraRows)})});setExtraRows([]);await reload()}catch(error){setExtraError(error.message)}finally{setExtraBusy(false)}};
  const removeExtra=async extra=>{if(!window.confirm(`Снять ауд. ${extra.room_number} (${extra.room_purpose}) из комплекта?`))return;setExtraError('');try{if(extra.status==='pending')await request(`/api/admin/bookings/${extra.id}/reject`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'Снята из комплекта администратором'})});else await request(`/api/admin/booking-center/${extra.id}/cancel`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'Снята из комплекта',comment:'Аудитория больше не нужна в комплекте',replacement_offered:false,notify_customer:false})});await reload()}catch(error){setExtraError(error.message)}};
  const addComment=async event=>{event.preventDefault();try{await request(`/api/admin/booking-center/${item.id}/comments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:comment})});setComment('');await reload()}catch(error){setCommentError(error.message)}};
  return <div className="center-modal"><button className="center-backdrop" onClick={close}/><aside className="booking-detail-panel"><header><div><small>БРОНИРОВАНИЕ № {item.id}</small><h2>{item.title}</h2></div><button className="icon" onClick={close}><X/></button></header>
    <div className={`system-recommendation ${(item.assessment?.available&&item.assessment?.capacity_ok!==false)?'good':'bad'}`}>{(item.assessment?.available&&item.assessment?.capacity_ok!==false)?<ShieldCheck/>:<AlertTriangle/>}<span><b>{(item.assessment?.available&&item.assessment?.capacity_ok!==false)?'Аудитория доступна':'Нужна проверка'}</b>{item.assessment?.message}</span></div>
    <section className="booking-detail-chat"><BookingChatLink item={item}/></section>
    <section><h3>Запрос</h3><ShortNoticeBadge item={item}/><dl className="detail-grid"><div><dt>Формат мероприятия</dt><dd>{item.event_format||'Другое'}</dd></div><div><dt>Дата проведения</dt><dd>{formatDate(item.date)}</dd></div><div><dt>Аудитория</dt><dd>Ауд. {item.room_number}, {item.building}</dd></div><div><dt>Заказчик</dt><dd>{item.customer_name||'Не указан'}{item.customer_contact?` · ${item.customer_contact}`:''}</dd></div><div><dt>Ответственный</dt><dd>{item.owner_name}</dd></div><div><dt>Подразделение</dt><dd>{item.department_name||'Не указано'}</dd></div><div><dt>Источник</dt><dd>{SOURCE_LABELS[item.source]||item.source}</dd></div><div><dt>Номер заявки</dt><dd>{item.external_reference||'Нет'}</dd></div><div><dt>Участники</dt><dd>{item.participants||'Не указано'}</dd></div><div><dt>Дополнительное оснащение</dt><dd>{(item.requested_equipment||[]).join(', ')||'Не запрошено'}</dd></div><div><dt>Комментарий к заявке</dt><dd>{item.comment||'Нет'}</dd></div></dl>{item.transfer_reason&&<div className="detail-cancellation transfer"><b>Причина переноса: {item.transfer_reason}</b>{item.previous_booking_id&&<p>Исходная бронь № {item.previous_booking_id} сохранена в истории.</p>}</div>}{item.cancellation_reason&&<div className="detail-cancellation"><b>Причина отмены: {item.cancellation_reason}</b><p>{item.cancellation_comment}</p><small>Отменил(а): {item.cancelled_by} · {formatMoment(item.cancelled_at)}</small>{item.notify_customer&&<small>Отмечено: нужно дополнительно сообщить заказчику</small>}</div>}</section>
    {item.record_kind==='booking'&&<section><h3>Организация мероприятия</h3><BookingQuestionSummary item={item}/></section>}
    <BookingObservers bookingId={item.id} initial={item.observers||[]} request={request} onChanged={reload}/>
    <section>{item.parent&&<div className="detail-cancellation transfer"><b>Дополнительная аудитория комплекта: {item.room_purpose}</b><p>Основная бронь № {item.parent.id} · ауд. {item.parent.room_number} — {item.parent.title}</p></div>}{!item.parent_booking_id&&<><RoomSetList extras={item.extra_rooms||[]} title="Комплект: дополнительные аудитории" actions={extra=>['pending','approved'].includes(extra.status)&&<button className="secondary" onClick={()=>removeExtra(extra)}>Снять из комплекта</button>}/>{!CLOSED.includes(item.status)&&item.record_kind==='booking'&&<div className="room-set-add"><ExtraRoomsPicker request={request} availabilityUrl="/api/admin/availability" date={item.date} timeStart={item.time_start} timeEnd={item.time_end} mainRoomId={item.room_id} value={extraRows} onChange={setExtraRows}/>{extraRows.length>0&&<button className="primary" disabled={extraBusy} onClick={addExtras}>{extraBusy?'Сохраняем…':'Добавить в комплект'}</button>}</div>}</>}{extraError&&<p className="error">{extraError}</p>}</section>
    <section><AttachmentList title="Файлы заявки" items={item.attachments||[]} request={request} user={{role:'admin'}} uploadTarget={{bookingId:item.id}} onChanged={reload}/></section><section className="booking-comments"><h3><MessageSquarePlus/>Рабочие комментарии</h3><form onSubmit={addComment}><textarea value={comment} onChange={event=>setComment(event.target.value)} required minLength="2" placeholder="Комментарий, поручение или уточнение для коллег"/><button className="primary">Добавить</button></form>{commentError&&<p className="error">{commentError}</p>}<div>{item.comments?.map(entry=><article key={entry.id}><span><b>{entry.author}</b><time>{formatMoment(entry.created_at)}</time><p>{entry.text}</p></span></article>)}</div></section>
    <section><h3><History/>Путь заявки</h3><div className="booking-timeline">{item.events?.map(event=><article key={event.id}><i/><div><b>{event.summary}</b><p>{event.actor}</p>{event.data?.reason&&<p>Причина: {event.data.reason}</p>}{event.data?.comment&&<p>Комментарий: {event.data.comment}</p>}<time>{formatMoment(event.created_at)}</time></div></article>)}</div></section>
    <footer>{!CLOSED.includes(item.status)&&item.record_kind==='booking'&&<><button className="secondary" onClick={alternatives}>Найти замену</button><button className="secondary" onClick={edit}>Изменить</button><button className="secondary" onClick={transfer}>Перенести</button></>}{item.status==='pending'&&<button className="primary" onClick={()=>status('approved')}>Подтвердить</button>}{item.status==='approved'&&item.record_kind==='booking'&&eventStarted(item)&&<>{eventFinished(item)&&<button className="secondary" onClick={()=>status('completed')}>Состоялось</button>}<button className="secondary" onClick={()=>status('no_show')}>Неявка</button></>}{item.status==='completed'&&item.record_kind==='booking'&&<button className="secondary" onClick={()=>status('no_show')}>Отметить неявку</button>}{item.status==='no_show'&&eventFinished(item)&&<button className="secondary" onClick={()=>status('completed')}>Всё же состоялось</button>}{!CLOSED.includes(item.status)&&<button className="soft-danger" onClick={cancel}>Отменить</button>}{canArchive(item)&&<button className="archive-button" onClick={archive}><Archive/>{item.archived_at?'Вернуть из архива':'В архив'}</button>}<button className="delete-booking-button" onClick={remove}><Trash2/>Удалить</button></footer>
  </aside></div>
}

function RejectBookingDialog({item,close,submit}){const [reason,setReason]=useState('');return <div className="center-modal nested"><button className="center-backdrop" onClick={close}/><form className="action-dialog" onSubmit={event=>{event.preventDefault();submit(reason)}}><header><div><small>{item.series_items?`РЕШЕНИЕ ПО СЕРИИ · ${item.series_count} БРОНИРОВАНИЙ`:`РЕШЕНИЕ ПО ЗАЯВКЕ № ${item.id}`}</small><h2>{item.series_items?'Отклонить серию':'Отклонить заявку'}</h2></div><button type="button" className="icon" onClick={close}><X/></button></header><p>Пользователь увидит эту причину в истории заявки.</p><label><span>Причина отказа</span><textarea value={reason} onChange={event=>setReason(event.target.value)} required minLength="2" placeholder="Объясните причину и при необходимости предложите другой вариант"/></label><footer><button type="button" className="secondary" onClick={close}>Назад</button><button className="soft-danger">Отклонить заявку</button></footer></form></div>}

function CancelDialog({item,request,close,done}){const targets=entriesOf(item).filter(entry=>!CLOSED.includes(entry.status));const [saving,setSaving]=useState(false);const [error,setError]=useState('');const submit=async e=>{e.preventDefault();setSaving(true);const form=new FormData(e.currentTarget);const body=JSON.stringify({reason:form.get('reason'),comment:form.get('comment'),replacement_offered:form.has('replacement_offered'),notify_customer:form.has('notify_customer')});try{if(item.series_items&&item.series_id)await request(`/api/admin/booking-series/${item.series_id}/cancel`,{method:'POST',headers:{'Content-Type':'application/json'},body});else await request(`/api/admin/booking-center/${item.id}/cancel`,{method:'POST',headers:{'Content-Type':'application/json'},body});done()}catch(err){setError(err.message);setSaving(false)}};return <div className="center-modal nested"><button className="center-backdrop" onClick={close}/><form className="action-dialog" onSubmit={submit}><header><div><small>ОТМЕНА С СОХРАНЕНИЕМ ИСТОРИИ</small><h2>{item.series_items?'Отменить серию':'Отменить бронирование'}</h2></div><button type="button" className="icon" onClick={close}><X/></button></header>{item.series_items&&<p><b>Будет отменено записей серии: {targets.length}.</b></p>}{item.set_extras?.length>0&&<p><b>При отмене основной аудитории будут также отменены открытые дополнительные аудитории комплекта.</b></p>}<p>Бронь не будет удалена. Факт отмены, причина, комментарий и ответственный администратор сохранятся в истории.</p><label><span>Причина отмены</span><select name="reason" required><option value="">Выберите причину</option><option>Отмена заказчиком</option><option>Изменение планов подразделения</option><option>Техническая недоступность аудитории</option><option>Перенос мероприятия</option><option>Другая причина</option></select></label><label><span>Комментарий</span><textarea name="comment" required minLength="2" placeholder="Уточните обстоятельства отмены"/></label><label className="check-row"><input type="checkbox" name="replacement_offered"/><span>Заказчику предложена замена</span></label><label className="check-row"><input type="checkbox" name="notify_customer" defaultChecked/><span>Нужно дополнительно сообщить заказчику (звонок или письмо)</span></label>{error&&<p className="error">{error}</p>}<footer><button type="button" className="secondary" onClick={close}>Назад</button><button className="soft-danger" disabled={saving}>{saving?'Сохраняем…':'Подтвердить отмену'}</button></footer></form></div>}

function DeleteBookingDialog({item,request,close,done}){const [saving,setSaving]=useState(false);const [error,setError]=useState('');const remove=async()=>{setSaving(true);setError('');try{await request('/api/admin/booking-bulk/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:entriesOf(item).map(entry=>entry.id)})});await done()}catch(failure){setError(failure.message);setSaving(false)}};return <div className="center-modal nested"><button className="center-backdrop" onClick={close}/><section className="action-dialog delete-booking-dialog" role="dialog" aria-modal="true"><header><div><small>БЕЗВОЗВРАТНОЕ УДАЛЕНИЕ</small><h2>{item.series_items?`Точно удалить всю серию (${item.series_count})?`:'Точно удалить бронь?'}</h2></div><button type="button" className="icon" onClick={close}><X/></button></header><div className="delete-booking-warning"><AlertTriangle/><span><b>Это действие нельзя отменить</b><p>Бронь и связанная с ней история будут полностью удалены. Если это основная аудитория комплекта, дополнительные аудитории тоже будут удалены. Для обычной отмены используйте кнопку «Отменить».</p></span></div><div className="delete-booking-summary"><strong>{item.title}</strong><span>{item.series_items?`${formatDate(item.series_dates[0])} — ${formatDate(item.series_dates[1])}`:formatDate(item.date)}</span><b>{item.building} · аудитория {item.room_number}</b></div>{error&&<p className="error">{error}</p>}<footer><button type="button" className="secondary" onClick={close}>Нет, оставить</button><button type="button" className="confirm-delete-button" disabled={saving} onClick={remove}><Trash2/>{saving?'Удаляем…':'Да, удалить безвозвратно'}</button></footer></section></div>}

function EditBooking({item,rooms,departments,request,close,done}){
  // The lists hold only active rooms and departments; keep the booking's own ones selectable
  // so opening the form never silently moves the booking elsewhere.
  const roomOptions=rooms.some(room=>room.id===item.room_id)?rooms:[{id:item.room_id,number:item.room_number,building:item.building,inactive:true},...rooms];
  const departmentOptions=!item.department_id||departments.some(department=>department.id===item.department_id)?departments:[{id:item.department_id,code:item.department_code,name:item.department_name},...departments];const [error,setError]=useState('');const [saving,setSaving]=useState(false);const [equipmentRoomId,setEquipmentRoomId]=useState(String(item.room_id));const [questions,setQuestions]=useState(()=>bookingQuestionAnswers(item));const submit=async e=>{e.preventDefault();setSaving(true);const data=Object.fromEntries(new FormData(e.currentTarget));data.room_id=Number(data.room_id);data.department_id=Number(data.department_id);data.participants=Number(data.participants);if(item.record_kind==='booking')Object.assign(data,bookingQuestionAnswers(questions));try{await request(`/api/admin/booking-center/${item.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});done()}catch(err){setError(err.message);setSaving(false)}};return <div className="center-modal nested"><button className="center-backdrop" onClick={close}/><form className="action-dialog edit-booking-dialog" onSubmit={submit}><header><div><small>КОРРЕКТИРОВКА БРОНИРОВАНИЯ</small><h2>Изменить параметры</h2></div><button type="button" className="icon" onClick={close}><X/></button></header><div className="wizard-fields"><label className="full"><span>Аудитория *</span><select name="room_id" value={equipmentRoomId} onChange={event=>setEquipmentRoomId(event.target.value)} required>{roomOptions.map(room=><option value={room.id} key={room.id}>{room.number} · {room.building} · {room.inactive?'отключена':`${room.capacity} мест`}</option>)}</select></label><label><span>Дата *</span><input name="date" type="date" lang="ru" defaultValue={item.date} onChange={()=>setError('')} required/></label><label><span>Участников *</span><input name="participants" type="number" min="1" defaultValue={item.participants||''} required/></label><label className="full"><span>Название *</span><input name="title" defaultValue={item.title} required minLength="2"/></label><label><span>ФИО ответственного *</span><input name="customer_name" defaultValue={item.customer_name||''} required minLength="2"/></label><label><span>Подразделение *</span><select name="department_id" defaultValue={item.department_id||''} required><option value="" disabled>Выберите подразделение</option>{departmentOptions.map(department=><option value={department.id} key={department.id}>{department.name}</option>)}</select></label><label><span>Телефон *</span><input name="customer_contact" type="tel" defaultValue={item.contact_phone!==undefined?(item.contact_phone||''):(item.customer_contact||'')} required minLength="3"/></label><RoomEquipmentBlock className="full" rooms={[rooms.find(room=>String(room.id)===equipmentRoomId)]}/>{item.record_kind==='booking'&&<BookingQuestions form={questions} update={(key,value)=>setQuestions(old=>({...old,[key]:value}))}/>}<label className="full"><span>Комментарий *</span><textarea name="comment" defaultValue={item.comment||''} required minLength="2"/></label></div>{error&&<p className="error">{error}</p>}<footer><button type="button" className="secondary" onClick={close}>Отмена</button><button className="primary" disabled={saving}>{saving?'Проверяем…':'Сохранить изменения'}</button></footer></form></div>}
